// === Tab: main.js ===
/*
Fire brush 2 (sprites) 

Another attempt at fire and smoke using sprites.

Controls:
	- Drag the mouse.
	- Press any key to change display type.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

// Contains images.
var fireSourceImgs = [];
var smokeSourceImgs = [];

// A multi-dimentional list that contains lists of images.
var fireImgs = [];
var smokeImgs = [];

var smokeParticles = [];
var fireParticles = [];

var drawMode = 0;


// Load all sprites in advanced.
function preload() {
	fireSourceImgs.push(loadImage("https://openprocessing.org/sketch/650512/files/fire1.png"));
	fireSourceImgs.push(loadImage("https://openprocessing.org/sketch/650512/files/fire2.png"));
	fireSourceImgs.push(loadImage("https://openprocessing.org/sketch/650512/files/fire3.png"));

	smokeSourceImgs.push(loadImage("https://openprocessing.org/sketch/650512/files/smoke1.png"));
	smokeSourceImgs.push(loadImage("https://openprocessing.org/sketch/650512/files/smoke2.png"));
}


function setup() {
  createCanvas(windowWidth, windowHeight);

	textAlign(CENTER);

	createImgOpacitySequence(fireSourceImgs, fireImgs);
	createImgOpacitySequence(smokeSourceImgs, smokeImgs);
} 


function draw() {
  // Increases red hue the more there is fire on-screen.
	let fireAmount = fireParticles.length * 0.75;
  background(255, 255 - fireAmount, 255 - fireAmount);

  // Spawn fire particles.
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == LEFT) {
		for (let i = 0; i < 3; i++) {
  		fireParticles.push(new Fire((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
		}
  }

  // Move and show smoke particles.
  for (var i = smokeParticles.length-1; i > -1; i--) {
    smokeParticles[i].move();
    smokeParticles[i].display();

    if (smokeParticles[i].life <= 0) {
      smokeParticles.splice(i, 1);
    }
  }

  // Move and show fire particles.
  // Always draw in front of smoke.
  for (var i = fireParticles.length-1; i > -1; i--) {
    fireParticles[i].move();

		if (drawMode != 1) {
    	fireParticles[i].display();
		}

    if (fireParticles[i].life <= 0) {
      fireParticles.splice(i, 1);
    }
  }

	// Show tooltip.
	noStroke();
	fill(0);
	let tooltip = "".concat("Drag the mouse to create fire\n", 
												 	"Press any key to change display type");
	text(tooltip, width/2, height-75);
}


function keyPressed() {
	drawMode++;
	if (drawMode > 2) {
		drawMode = 0;
	}
}


// Takes all images in sourceImgs and creates a sequence of new images with different transparency.
// The idea is to directly reference an image at a certain opacity without having to use 'tint' in draw().
// This significantly increases performance because all the heavy work is done in setup().
function createImgOpacitySequence(sourceImgs, outImgs) {
	for (let n = 0; n < sourceImgs.length; n++) {
		let imgSequence = [];

		sourceImgs[n].loadPixels();

		// The lower 'i' is, the more opacity there is to map to later, but this means it'll be heavier.
		// 20 seems to be a good balance of looking good and speed.
		for (let i = 255; i > -1; i-=20) {
			let opacity = map(i, 255, 0, 1, 0);

			let img = createImage(sourceImgs[n].width, sourceImgs[n].height);
			img.loadPixels();

			for (var j = 0; j < sourceImgs[n].width*sourceImgs[n].height*4; j+=4) {
				img.pixels[j] = red(sourceImgs[n].pixels[j]);
				img.pixels[j+1] = green(sourceImgs[n].pixels[j+1]);
				img.pixels[j+2] = blue(sourceImgs[n].pixels[j+2]);
				img.pixels[j+3] = sourceImgs[n].pixels[j+3]*opacity;
			}

			img.updatePixels();
			imgSequence.push(img);
		}

		outImgs.push(imgSequence);
	}	
}

// === Tab: fire.js ===
var maxFireLife = 25;


function Fire(x, y) {

  this.pos = new p5.Vector(x + random(-20, 20), y + random(-20, 20));
  this.vel = new p5.Vector();

  this.push = random(5, 15);

  this.angle = random(0, 360);
  this.angleRate = random(-3, 3);

	this.scaleVariation = random(0.5, 2);

  this.life = maxFireLife;
  this.lifeRate = random(0.35, 1);

	// Pick random image.
	this.imgIndex = int(random(fireImgs.length));

  this.move = function() {
    this.life = max(0, this.life - this.lifeRate);

    // Add gravity and move.
    this.vel.y += 0.015;
    this.pos.add(this.vel);

		// Increase rotation.
		this.angle += this.angleRate;

    // Has a chance to spawn smoke particles.
		if (this.life > maxFireLife * 0.75) {
			if (int(random(10)) == 0) {
				var spawnCount = int(random(2)) + 1;
				for (var i = 0; i < spawnCount; i++) {
					this.spawnSmoke();
				}
			}
		}
  }

  this.spawnSmoke = function() {
    var offset = map(this.life, maxFireLife, 0, 0, this.push);

    smokeParticles.push(new Smoke(this.pos.x, this.pos.y, offset, this.angle));
  }

  this.display = function() {
    push();

    translate(this.pos.x, this.pos.y);

		scale(map(this.life, maxFireLife, 0, 0, 1.25) * this.scaleVariation);
    rotate(radians(this.angle));
    translate(map(this.life, maxFireLife, 0, 0, this.push * 2), 0);

		var opacity = map(this.life, maxFireLife, 0, 200, 0);

		if (drawMode == 0) {
			// Display fire sprite.
			// Map life to an index of the image sequence with approriate opacity.
			let imgSequenceIndex = floor(map(this.life, maxFireLife, 0, 0, fireImgs[this.imgIndex].length-1));
			var img = fireImgs[this.imgIndex][imgSequenceIndex];
			image(img, -img.width/2, -img.height/2);
		} else {
			// Display as a point.
			stroke(200, 50, 0, opacity);
			strokeWeight(60);
			point(0, 0);
		}

    pop();
  }
}

// === Tab: smoke.js ===
var maxSmokeLife = 40;


function Smoke(x, y, offset, parentAngle) {

  this.pos = new p5.Vector(x, y);
  this.offset = offset;
  this.push = random(-100, -10);

  this.parentAngle = parentAngle;
  this.angle = random(-45, 45);
  this.angleRate = random(-2, 2);

	this.scaleVariation = random(0.25, 1.25);

  this.life = maxSmokeLife;
  this.lifeRate = random(0.4, 1.25);

	this.imgIndex = int(random(smokeImgs.length));

  this.move = function() {
    this.life = max(0, this.life - this.lifeRate);
    this.angle += this.angleRate;
  }

  this.display = function() {
    push();

    // This would be much easier if I had its parent's world position!
    // Instead just mimic its parent at the time of its spawn.
    translate(this.pos.x, this.pos.y);
    rotate(radians(this.parentAngle));
    translate(this.offset, 0);
    rotate(radians(-this.parentAngle));

    rotate(radians(this.angle));
    translate(0, map(this.life, maxSmokeLife, 0, 0, this.push));
    scale(map(this.life, maxSmokeLife, 0, 0, 3) * this.scaleVariation);

		var opacity = map(this.life, maxSmokeLife, 0, 255, 0);

		if (drawMode != 2) {
			// Display smoke sprite.
			// Map life to an index of the image sequence with approriate opacity.
			var imgSequenceIndex = int(map(this.life, maxSmokeLife, 0, 0, smokeImgs[this.imgIndex].length-1));
			var img = smokeImgs[this.imgIndex][imgSequenceIndex];
			image(img, 0, 0);
		} else {
			// Display as a point.
			stroke(0, opacity);
			strokeWeight(30);
			point(0, 0);
		}

		pop();
  }
}

